'use strict';
(() => {
  const $ = (s) => document.querySelector(s);
  const all = (s) => [...document.querySelectorAll(s)];
  const input = $('#portion-count');
  const format = (n) => Number(n.toFixed(3)).toLocaleString('en-GB',{maximumFractionDigits:3});
  const rows = [
    {name:'Beef',per:.18,unit:'kg',stock:4,pack:2,packName:'tray',supplier:'Keukenpartner',recipe:'180 g'},
    {name:'Brioche buns',per:1,unit:'pcs',stock:12,pack:8,packName:'bag',supplier:'Keukenpartner',recipe:'1 pc'},
    {name:'Tomatoes',per:.04,unit:'kg',stock:6,pack:3,packName:'crate',supplier:'Groen & Vers',recipe:'40 g'},
    {name:'Lettuce',per:.03,unit:'kg',stock:1,pack:.5,packName:'bag',supplier:'Groen & Vers',recipe:'30 g'},
    {name:'Burger sauce',per:.025,unit:'l',stock:1,pack:1,packName:'bottle',supplier:'Keukenpartner',recipe:'25 ml'},
    {name:'Fries',per:.15,unit:'kg',stock:6,pack:2.5,packName:'bag',supplier:'Keukenpartner',recipe:'150 g'}
  ];
  let portions=32,view='recept',completed=new Set(),tourTimer=null,tourStarted=0,tourElapsed=0,tourStep=-1,tourTouched=false;
  const tourLength=22000;
  const calc=(n)=>rows.map(r=>{const need=+(n*r.per).toFixed(4),shortage=Math.max(0,+(need-r.stock).toFixed(4)),packs=Math.ceil((shortage-1e-9)/r.pack);return {...r,need,shortage,packs:Math.max(0,packs),order:+(Math.max(0,packs)*r.pack).toFixed(4)};});
  function render(){
    const data=calc(portions);
    all('.portions-label').forEach(el=>el.textContent=`${portions} portions`);
    $('#recipe-table').innerHTML='<table class="product-table"><thead><tr><th scope="col">Product</th><th scope="col">Per portion</th><th scope="col">Needed</th></tr></thead><tbody>'+data.map(r=>`<tr><td>${r.name}</td><td class="product-per">${r.recipe}</td><td>${format(r.need)} ${r.unit}</td></tr>`).join('')+'</tbody></table>';
    $('#stock-table').innerHTML='<table class="product-table"><thead><tr><th scope="col">Product</th><th scope="col">In stock</th><th scope="col">Shortfall</th></tr></thead><tbody>'+data.map(r=>`<tr><td>${r.name}</td><td class="product-per">${format(r.stock)} ${r.unit}</td><td>${r.shortage?format(r.shortage)+' '+r.unit:'Enough'}</td></tr>`).join('')+'</tbody></table>';
    const mep=[['burgers','Shape the burgers',`${format(portions*.18)} kg beef`,`${portions} pcs`],['groenten','Slice the vegetables',`${format(portions*.04)} kg tomatoes · ${format(portions*.03)} kg lettuce`,`${portions} portions`],['friet','Portion the fries','Get ready for service',`${format(portions*.15)} kg`]];
    $('#mep-list').innerHTML=mep.map(([id,title,detail,amount])=>`<label class="mep-row"><input type="checkbox" data-task="${id}" ${completed.has(id)?'checked':''}><span>${title}<small>${detail}</small></span><b>${amount}</b></label>`).join('');
    const orders=data.filter(r=>r.order>0);
    $('#order-count').textContent=`${orders.length} ingredients`;
    $('#order-list').innerHTML=orders.length?['Keukenpartner','Groen & Vers'].map(s=>{const group=orders.filter(r=>r.supplier===s);return group.length?`<h4 class="supplier-heading">${s} · sample supplier</h4>`+group.map(r=>`<div class="order-row"><div>${r.name}<small>${format(r.need)} needed − ${format(r.stock)} in stock = ${format(r.shortage)} ${r.unit} shortfall</small></div><strong>${format(r.order)} ${r.unit}<small>${r.packs} × ${format(r.pack)} ${r.unit}</small></strong></div>`).join(''):'';}).join(''):'<p class="order-empty">Everything is in stock. No top-up is needed.</p>';
    $('#result-summary').textContent=`${portions} portions · ${orders.length} ingredients to replenish`;
    $('#portion-less').disabled=portions<=1;
    $('#portion-more').disabled=portions>=500;
  }
  function setView(next,focus=false){
    if(!['recept','mep','voorraad','bestellen'].includes(next))return;
    view=next;
    all('[data-view]').forEach(button=>{const active=button.dataset.view===view;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;});
    all('.product-pane').forEach(p=>p.hidden=p.id!==`pane-${view}`);
    if(focus)$(`#tab-${view}`).focus();
  }
  function valid(){const raw=input.value.trim(),n=Number(raw);return raw!==''&&Number.isInteger(n)&&n>=1&&n<=500;}
  function update(n){portions=n;input.value=String(n);input.removeAttribute('aria-invalid');$('#quantity-error').hidden=true;completed.clear();render();}
  function stopTour(reset=false){if(tourTimer)clearInterval(tourTimer);tourTimer=null;$('#tour-button').setAttribute('aria-pressed','false');$('#tour-label').textContent=reset?'Watch the product tour':'Resume tour';$('#tour-button use').setAttribute('href','/assets/icons.svg#play');if(reset){tourElapsed=0;tourStep=-1;tourTouched=false;$('#tour-progress').style.width='0%';$('#tour-status').textContent='From plan to order list';}}
  function manual(){if(tourTouched)stopTour(true);}
  input.addEventListener('input',()=>{manual();if(valid())update(Number(input.value));else{$('#quantity-error').textContent='Enter a whole number from 1 to 500.';$('#quantity-error').hidden=false;input.setAttribute('aria-invalid','true');$('#portion-less').disabled=false;$('#portion-more').disabled=false;}});
  $('#portion-less').addEventListener('click',()=>{manual();update(Math.max(1,Math.min(500,valid()?Number(input.value)-1:Math.floor(Number(input.value)||portions))));});
  $('#portion-more').addEventListener('click',()=>{manual();update(Math.min(500,Math.max(1,valid()?Number(input.value)+1:Math.ceil(Number(input.value)||portions))));});
  all('[data-view]').forEach(button=>{button.addEventListener('click',()=>{manual();setView(button.dataset.view);});button.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();manual();const list=['recept','mep','voorraad','bestellen'];let i=list.indexOf(view);i=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;setView(list[i],true);});});
  $('#mep-list').addEventListener('change',event=>{if(!event.target.matches('[data-task]'))return;manual();const id=event.target.dataset.task;event.target.checked?completed.add(id):completed.delete(id);});
  all('[data-open-view]').forEach(link=>link.addEventListener('click',()=>{manual();setView(link.dataset.openView);}));
  function runTour(){
    const elapsed=tourElapsed+performance.now()-tourStarted;
    $('#tour-progress').style.width=`${Math.min(100,elapsed/tourLength*100)}%`;
    const step=elapsed<3500?0:elapsed<7500?1:elapsed<12000?2:elapsed<16500?3:4;
    if(step!==tourStep){tourStep=step;const count=step===0?32:48;if(portions!==count||!valid())update(count);setView(['recept','recept','mep','voorraad','bestellen'][step]);$('#tour-status').textContent=['1/4 · Start with your dish','1/4 · From 32 to 48 portions','2/4 · Your prep updates','3/4 · Subtract your stock','4/4 · Your order list is ready'][step];}
    if(elapsed>=tourLength){stopTour(false);tourElapsed=0;tourStep=-1;$('#tour-label').textContent='Replay the tour';$('#tour-status').textContent='48 portions. One connected plan.';$('#tour-progress').style.width='100%';}
  }
  $('#tour-button').addEventListener('click',()=>{if(tourTimer){tourElapsed+=performance.now()-tourStarted;stopTour(false);$('#tour-status').textContent='Paused';return;}tourTouched=true;tourStep=-1;tourStarted=performance.now();$('#tour-button').setAttribute('aria-pressed','true');$('#tour-label').textContent='Pause tour';$('#tour-button use').setAttribute('href','/assets/icons.svg#pause');tourTimer=setInterval(runTour,150);runTour();});
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&tourTimer){tourElapsed+=performance.now()-tourStarted;stopTour(false);$('#tour-status').textContent='Paused';}});
  const menu=$('.menu-toggle'),nav=$('#site-navigation');
  function closeMenu(){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');}
  menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);});
  nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});
  document.addEventListener('click',e=>{if(menu.getAttribute('aria-expanded')==='true'&&!e.target.closest('.site-header'))closeMenu();});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
  render();
})();
